SELECT DISTINCT l.id AS level_id,s.workshop_id, coalesce(to_jsonb(s.authors),'null'::jsonb) AS authors,l.xx_hash,l.adventure, l.date_created::text AS date_created,coalesce(i.name,v.payload->>'name') AS name, coalesce(nullif(i.image_url,''),nullif(other_image.image_url,''),nullif(wi.image_url,'')) AS image_url, coalesce(u.steam_name,v.payload->>'author') AS author_name, p.points,p.rating, (SELECT count(*) FROM (SELECT eligible_source.* FROM public.record eligible_source WHERE NOT EXISTS(SELECT 1 FROM zc_private.record_validation invalid WHERE invalid.id_record=eligible_source.id AND invalid.status='fail')) r WHERE r.id_level=l.id) AS record_count, (SELECT count(*) FROM (SELECT eligible_source.* FROM public.personal_best_global eligible_source WHERE NOT EXISTS(SELECT 1 FROM zc_private.record_validation invalid WHERE invalid.id_record=eligible_source.id_record AND invalid.status='fail')) pb WHERE pb.id_level=l.id) AS personal_best_count, (SELECT count(*) FROM public.vote vote WHERE vote.id_level=l.id) AS vote_count {{candidates_from_sql}} ORDER BY level_id,workshop_id
